with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '絵画芸術', 'ヨハネス・フェルメール', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Jan_Vermeer_-_The_Art_of_Painting_-_Google_Art_Project.jpg/960px-Jan_Vermeer_-_The_Art_of_Painting_-_Google_Art_Project.jpg', '1666年ごろの作品で、ウィーン美術史美術館が所蔵します。顔の見えない画家が、月桂冠をかぶりトランペットと書物を持つモデルを描く場面で、モデルは歴史の女神クリオとする説が有力です。背景の大きなネーデルラント地図には南北を分ける裂け目があり、国の分断を表すともいわれます。フェルメールの死後も家族が手放さず、1940年にはヒトラーが買い取った波乱の来歴をもちます。カーテンの奥をのぞくような構図と、静かな光に注目してください。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jan_Vermeer_-_The_Art_of_Painting_-_Google_Art_Project.jpg'),
    (2, '冨嶽三十六景 山下白雨', '葛飾北斎', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Lightnings_below_the_summit.jpg/960px-Lightnings_below_the_summit.jpg', '葛飾北斎の連作「冨嶽三十六景」の一図で、1831年ごろに版元の永寿堂（西村屋与八）から出たと考えられています。晴れた山頂を見せる富士の麓では、黒い山肌に稲妻が走り、にわか雨が降っています。赤く染まる富士を描いた「凱風快晴」の「赤富士」に対して「黒富士」と呼ばれ、「神奈川沖浪裏」とともにシリーズの三大傑作に数えられます。山の上と下で天気がまったく違う、大きな富士ならではの姿を一枚に収めた発想に注目です。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Lightnings_below_the_summit.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('草間彌生の作品、約24億円で最高落札記録', '草間彌生の初期作《No. 3P.B.》が、ニューヨークのサザビーズで約24億円で落札され、作家の最高記録を更新した。', '11月16日にニューヨークで開かれたサザビーズの現代美術イブニングセールで、草間彌生の油彩画《No. 3P.B.》（1960年）が手数料込み1510万ドル（約24億円）で落札され、草間作品のオークション最高落札記録を更新した。初期の「インフィニティ・ネット」シリーズを代表する作品で、1961年にはホイットニー美術館の年次展に出品されている。同じセールでは、サム・フランシス《Towards Disappearance I》（1958）も1710万ドルで落札され、作家の最高記録を27年ぶりに更新した。セールの総額は約604億円と報じられている。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/market/33360',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ポーラ美術館、ゴンザレス＝トレスの代表作を収蔵', 'ポーラ美術館がフェリックス・ゴンザレス＝トレス《「無題」（パーフェクト・ラヴァーズ）》を新たに収蔵し、12月4日から公開する。', '神奈川県箱根町のポーラ美術館が、フェリックス・ゴンザレス＝トレスの代表作《「無題」（パーフェクト・ラヴァーズ）》（1987〜90年）を新たに収蔵した。同じ形の壁掛け時計2つを同じ時刻に合わせて並べた作品で、時計はやがてずれ、いずれ片方が先に止まる。1980年代のエイズ危機を背景に、作家と恋人の関係が投影されているとされる。12月4日から、開催中の「モネ没後100年・開館25周年記念 あたらしい目―モネと21世紀のアート」（2027年4月7日まで）で、作家のほかの3作品とともに公開される。', '', '美術館', 'https://bijutsutecho.com/magazine/news/headline/33354',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('安藤忠雄と「もの派」の展覧会、来春ヴェネチアで', 'ピノー・コレクションのプンタ・デラ・ドガーナで、安藤忠雄の建築写真ともの派の作品を組み合わせた展覧会が2027年3月に始まる。', 'イタリア・ヴェネチアのピノー・コレクションの美術館プンタ・デラ・ドガーナで、展覧会「Tadao Ando & Mono-ha. The Five Elements」が2027年3月21日から11月21日まで開かれる。安藤忠雄が自ら撮影した数百点の建築写真（初公開を含む）と、同コレクションが所蔵する「もの派」の作品を組み合わせ、両者の共通性を探る。構成は「空気」「土」「水」「火」「コンクリート」の5つの元素に基づく。会場は、安藤が歴史的建造物を改修して2009年に開館した美術館である。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33351',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('横浜で敦煌・シルクロード展、平山郁夫らの足跡', '莫高窟の世界遺産登録40周年を記念し、横浜ユーラシア文化館で2027年1月16日から敦煌とシルクロードの展覧会が開かれる。', '横浜ユーラシア文化館で、莫高窟世界遺産登録40周年記念「敦煌・シルクロードの風が立つー平山郁夫と江上波夫の足跡」が2027年1月16日から3月28日まで開かれる。莫高窟で発見された経典や仏画図録などで敦煌の仏教文化を紹介するとともに、日本のシルクロード人気を牽引した日本画家・平山郁夫、作家・井上靖、同館コレクションの核を築いた東洋学者・江上波夫の交流と業績を取り上げる。平山の《敦煌莫高窟》（1983年、平山郁夫シルクロード美術館蔵）なども展示される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33333',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('龍子記念館で近藤亜樹展、川端龍子と競演', '大田区立龍子記念館で11月21日から「近藤亜樹 吾は、わたしは、」が開かれ、川端龍子の作品と並べて展示する。', '大田区立龍子記念館で、高橋龍太郎コレクション連携企画「川端龍子プラスワン（後期）」として「近藤亜樹 吾は、わたしは、」が11月21日から2027年1月24日まで開かれる。川端龍子（1885〜1966）が自ら設立した記念館で、龍子作品と現代作家の作品を並べる企画で、前期の川内理香子に続き近藤亜樹が招かれた。近藤は1987年北海道生まれで、2020年から山形県を拠点に活動する。《ウータン山》（2010）や本展のための新作などが、龍子の《怒る富士》（1944）などと並ぶ。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33334',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('快楽の園', 'The Garden of Earthly Delights', 'ヒエロニムス・ボス', 'Hieronymus Bosch',
        1500,
        (select slug from public.art_movements where slug = 'renaissance'),
        'プラド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg/960px-The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg', '15世紀末から16世紀初めごろに描かれた三連祭壇画で、マドリードのプラド美術館が所蔵します。左翼はエデンの園、中央は裸の男女が果実や鳥、奇妙な建物の間で戯れる楽園のような世界、右翼は楽器や道具が拷問具となる地獄です。閉じると外側には天地創造の世界がモノクロームで描かれています。イタリアで理想の人体や遠近法が追求されたのと同じころ、北方のボスは中世の寓意を受け継ぎながら、細部に満ちた空想の世界を作り上げました。その奇想はブリューゲルに受け継がれ、のちにシュルレアリストたちにも注目されました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('雪中の狩人', 'Hunters in the Snow', 'ピーテル・ブリューゲル（父）', 'Pieter Bruegel the Elder',
        1565,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ウィーン美術史美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Pieter_Bruegel_the_Elder_-_Hunters_in_the_Snow_%28Winter%29_-_Google_Art_Project.jpg/960px-Pieter_Bruegel_the_Elder_-_Hunters_in_the_Snow_%28Winter%29_-_Google_Art_Project.jpg', '1565年に描かれ、ウィーン美術史美術館が所蔵する作品です。獲物の少ない狩りから犬を連れて戻る狩人たちが丘を下り、その先には凍った池で遊ぶ村人たちと、遠くの険しい山々が広がります。季節ごとの暮らしを描いた連作の一枚と考えられています。宗教や神話ではなく、農村の日常と自然そのものを主題にした点で、北方ルネサンスの風景画を大きく前進させました。斜めに下る構図で視線を奥へ導く工夫や、木々の黒いシルエットと雪の白の対比に注目してください。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Hunters_in_the_Snow_(Winter)_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ダイヤのエースを持ついかさま師', 'The Cheat with the Ace of Diamonds', 'ジョルジュ・ド・ラ・トゥール', 'Georges de La Tour',
        1635,
        (select slug from public.art_movements where slug = 'baroque'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Le_Tricheur_%C3%A0_l%27as_de_carreau_-_Georges_de_La_Tour_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1972_8.jpg/960px-Le_Tricheur_%C3%A0_l%27as_de_carreau_-_Georges_de_La_Tour_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1972_8.jpg', '1635年ごろの作品で、パリのルーヴル美術館が所蔵します。裕福な若者がカードに興じる横で、左の男は背中に隠したダイヤのエースを抜き取ろうとしています。中央の女と酒を運ぶ召使いは横目で合図を交わし、若者だけが企みに気づいていません。賭け事・酒・色恋という誘惑を戒める主題で、カラヴァッジョのいかさま師の絵に連なる風俗画の流れを受け継ぎつつ、ラ・トゥールは人物を単純な形にまとめ、静かな緊張感を生み出しました。視線と手の動きを追うと、場面の物語が読み取れます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Le_Tricheur_à_l''as_de_carreau_-_Georges_de_La_Tour_-_Musée_du_Louvre_Peintures_RF_1972_8.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
