    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('相馬の古内裏', 'Takiyasha the Witch and the Skeleton Spectre', '歌川国芳', 'Utagawa Kuniyoshi',
        1845,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Takiyasha_the_Witch_and_the_Skeleton_Spectre%2C_by_Utagawa_Kuniyoshi.jpg/960px-Takiyasha_the_Witch_and_the_Skeleton_Spectre%2C_by_Utagawa_Kuniyoshi.jpg', '弘化2〜3年（1845〜46年）ごろの作とされる歌川国芳の浮世絵版画です。山東京伝の読本『善知安方忠義伝』に取材し、平将門の遺児とされる滝夜叉姫が呼び出した巨大な骸骨が、荒れた古御所で大宅光圀に襲いかかる場面を描いています。原作では多数の骸骨が戦う場面ですが、国芳は画面を覆うほどの一体の大骸骨に描き替えました。骨格の写実性には西洋の解剖図の影響も指摘されます。役者絵や美人画が中心だった浮世絵に、武者絵や怪奇の大胆な表現を持ち込んだ国芳らしさがよく表れています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Takiyasha_the_Witch_and_the_Skeleton_Spectre,_by_Utagawa_Kuniyoshi.jpg')
on conflict (title, artist) do update set
