insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ピーテル・ブリューゲル（父）', 'Pieter Bruegel the Elder', 'ブリューゲル',
        null, 1569, 'west', array['renaissance']::text[],
        '農民の暮らしや風景を描いた、16世紀ネーデルラントを代表する画家。', '1525年から1530年ごろにブラバント地方で生まれたとされ、アントウェルペンでピーテル・クック・ファン・アールストに学んだと伝えられます。版画出版者ヒエロニムス・コックのもとで版画の下絵を手がけ、1551年から1554年ごろにはアルプスを越えてイタリアを旅しました。

初めはボスの影響を受けた寓意的な作品で「第二のボス」と呼ばれましたが、やがて農民の祭りや労働、季節の風景を主題にした作品を数多く描きました。宗教画や神話画が中心だった時代に、名もない人々の日常と自然そのものを絵の主役にしました。

代表作に「ネーデルラントの諺」（1559年）、「バベルの塔」（1563年ごろ）、「雪中の狩人」（1565年）、「農民の婚宴」（1568年）があります。1569年にブリュッセルで亡くなり、息子のピーテル・ブリューゲル（子）やヤン・ブリューゲル（父）も画家として活躍しました。', 'https://ja.wikipedia.org/wiki/%E3%83%94%E3%83%BC%E3%83%86%E3%83%AB%E3%83%BB%E3%83%96%E3%83%AA%E3%83%A5%E3%83%BC%E3%82%B2%E3%83%AB')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ハンス・ホルバイン（子）', 'Hans Holbein the Younger', 'ホルバイン',
        1497, 1543, 'west', array['renaissance']::text[],
        'ヘンリー8世の宮廷画家として活躍した、北方ルネサンスを代表する肖像画家。', '1497年末か1498年初めにアウクスブルクで、同名の画家ハンス・ホルバイン（父）の子として生まれました。1515年ごろからバーゼルやルツェルンで活動し、市長や裕福な市民のために肖像画や宗教画を描きました。

人文学者エラスムスの肖像を描いたことが縁で、トマス・モアを紹介され、1526年にロンドンへ渡ります。一度バーゼルに戻ったのち1532年に再びロンドンへ移り、1536年ごろにはヘンリー8世の宮廷画家となりました。細部まで正確な描写で、人物の地位や性格を伝える肖像画を数多く残しています。

代表作「大使たち」（1533年、ロンドン・ナショナル・ギャラリー）は、斜めから見ると正しい形になる髑髏の描写で知られます。1543年、ロンドンでペストのため亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%83%8F%E3%83%B3%E3%82%B9%E3%83%BB%E3%83%9B%E3%83%AB%E3%83%90%E3%82%A4%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジョルジュ・ド・ラ・トゥール', 'Georges de La Tour', 'ラ・トゥール',
        1593, 1652, 'west', array['baroque']::text[],
        'ろうそくの光に照らされた静かな夜の場面を描いた、17世紀フランスの画家。', '1593年、ロレーヌ公国のヴィック＝シュル＝セイユで生まれました。1617年にリュネヴィルへ移って工房を構え、1639年にはパリでルイ13世の国王付き画家の称号を得ています。

ろうそくや松明など一つの光源に照らされた夜の場面を多く描き、「夜の画家」と呼ばれます。強い明暗の対比にはカラヴァッジョの影響が見られますが、人物の形を単純にまとめ、静かで神秘的な雰囲気を生み出した点に独自性があります。昼の光の中での風俗画も描きました。

代表作に「ダイヤのエースを持ついかさま師」「大工の聖ヨセフ」（ともにルーヴル美術館）、「悔悛するマグダラのマリア」の連作があり、国立西洋美術館も「聖トマス」を所蔵しています。1652年にリュネヴィルでペストのため亡くなったのち長く忘れられ、20世紀になって再評価されました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A7%E3%83%AB%E3%82%B8%E3%83%A5%E3%83%BB%E3%83%89%E3%83%BB%E3%83%A9%E3%83%BB%E3%83%88%E3%82%A5%E3%83%BC%E3%83%AB')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
